text:
#resetColor {
  list-style-image: url("chrome://messenger/skin/icons/forget.svg");
  -moz-context-properties: fill;
  fill: currentColor;
  min-inline-size: 16px;
  min-block-size: 16px;
  padding: 2px !important;
  margin-inline-end: 4px;
  --toolbarbutton-background-color-hover: var(--button-hover-background-color);
  --toolbarbutton-hover-bordercolor: var(--button-border-color);
  --toolbarbutton-background-color-active: var(--button-active-background-color);
  --toolbarbutton-active-bordercolor: var(--button-border-color);

  &:not(:hover) {
    background-color: transparent;
  }

  & .button-icon {
    margin-inline-end: 0;
  }
}

button:focus-visible {
  outline: 2px solid var(--selected-item-color);
  outline-offset: -1px;
}
